-- The profession catalogs (issue #167), run against the real Data/ProfCatalog*.lua files and the TOC
-- under a stubbed retail client and a stubbed WoW: Forever one.
--
-- Each game has its own catalog, generated by tools/prof_catalog.py: Forever's classic professions,
-- and retail's current expansion (Midnight) only, with Jewelcrafting and Inscription. Exactly one of
-- them loads on each client, the TOC loads both files, and the professions panel has an icon for
-- every profession the catalog it loaded names.
--
--   luajit -e 'ADDON="."' tools/retail-professions.lua
--
-- Exits 1 on the first failed check.
ADDON = ADDON or "."

local checks = 0
local function check(cond, what)
  checks = checks + 1
  if not cond then
    io.stderr:write("FAIL: " .. what .. "\n")
    os.exit(1)
  end
end

local function read(rel)
  local fh = assert(io.open(ADDON .. "/" .. rel, "rb"), rel)
  local s = fh:read("*a")
  fh:close()
  return s
end

local function load(retail)
  GuildOS = { Client = { isAnniversary = false, isRetail = retail } }
  dofile(ADDON .. "/Data/ProfCatalogForever.lua")
  dofile(ADDON .. "/Data/ProfCatalogRetail.lua")
  return GuildOS.ProfCatalog
end

local retail = load(true)
check(retail and retail.build:match("^12%."), "retail loads the retail catalog")
check(retail.professions[755] and retail.professions[773], "with Jewelcrafting and Inscription")
check(retail.professions[129] == nil, "and no First Aid")
check(retail.professions[164].child == 2907, "its Blacksmithing is Midnight's")
local n = 0
for _ in pairs(retail.recipes) do n = n + 1 end
check(n > 500, "it lists the current expansion's recipes (" .. n .. ")")

local forever = load(false)
check(forever and forever.build:match("^1%.60"), "Forever loads its own catalog")
check(forever.professions[129] and forever.professions[755] == nil, "with First Aid and without Jewelcrafting")

GuildOS = { Client = { isAnniversary = true } }
dofile(ADDON .. "/Data/ProfCatalogForever.lua")
dofile(ADDON .. "/Data/ProfCatalogRetail.lua")
check(GuildOS.ProfCatalog == nil, "Anniversary loads neither")

local toc = read("GuildOS.toc")
check(toc:find("Data\\ProfCatalogForever.lua", 1, true) and toc:find("Data\\ProfCatalogRetail.lua", 1, true),
  "the TOC loads both catalogs")

-- Every profession either catalog names has its own icon in the panel.
local panel = read("UI/ProfessionsPanel.lua")
for _, cat in ipairs({ retail, forever }) do
  for line in pairs(cat.professions) do
    check(panel:find("[" .. line .. "] = \"Interface", 1, true), "the professions panel has an icon for line " .. line)
  end
end

print(("retail-professions: %d checks passed"):format(checks))
